//! Exact existing broker + actual native body + original resource wait. All
//! profiles/results are generated. No provider quota, live credentials or host IO.
use super::*;
use crate::pet_runtime::{peer_round_data::Captured,peer_round_review::{Review as DataReview,Observe},delegation_api::DelegationInput,planned_peer_tests::hybrid_delegation as hybrid,recipe_decisions::Source,Repository};
struct Observation{mode:u8,url:String,key:Option<String>}
fn data_configuration(provider:&str)->crate::pet_config::Configuration{let mut c=crate::pet_config::defaults();let pet=crate::pet_config::pet_id(provider).unwrap();c.pets.get_mut(pet).unwrap().provider=provider.into();c}
fn data_setup(provider:&'static str)->(Fixture,Authority,Record,Arc<Owned>,Chat,PreparedCall,Arc<DataReview>,Source,Observe,Arc<Mutex<Observation>>){
 let(f,a,g,o,main)=hybrid::published(provider,hybrid::cap());let store=Arc::new(Store::existing_verified(&f.path.join("goals"),&root(&f)).unwrap().unwrap());
 let config=data_configuration(provider);let mut settings=crate::settings::Settings::default();settings.active_integrations=vec!["ai_ollama".into(),"ai_lmstudio".into(),"integration_spotify".into()];
 let batch=crate::pet_runtime::peer_plan_review::Batch::capture(&o,&g,&config,&settings,crate::assistant_memory::now()).unwrap().unwrap();let observed:crate::pet_runtime::peer_plan_review::Observe=Arc::new(move||Ok((config.clone(),settings.clone())));
 let source=Source::capture_peer(o.clone(),&g,batch.clone(),store.clone(),observed.clone()).unwrap();let broker=crate::cli_chat::goal_decision_fixture(source);broker.panel_answer(true,broker.request["goalTarget"].clone()).unwrap();let choices=batch.approve(&broker.decision().unwrap(),&o,&g,&observed,crate::assistant_memory::now()).unwrap();for choice in choices{o.send_message(&g,&choice,crate::assistant_memory::now(),||observed()).unwrap();}
 let state=Arc::new(Mutex::new(Observation{mode:0,url:"http://127.0.0.1:11444".into(),key:None}));let state_ref=state.clone();let observe:Observe=Arc::new(move||{let s=state_ref.lock().unwrap();if s.mode==1{return Err(model::Error::Busy);}if s.mode==2{return Err(model::Error::StorageUnavailable);}Ok((data_configuration(provider),crate::local_chat::Server{id:provider,name:"Synthetic native DATA endpoint; no IO",url:s.url.clone(),key:s.key.clone()}))});let(_,server)=observe().unwrap();
 let data=Arc::new(Captured::at(&f.path.join("goals"),&root(&f),DelegationInput{pet_id:g.spec.owner.pet_id.clone(),goal_id:g.id.clone(),decision_id:o.lease().decision_id.clone()},&server,&o.lease().model,crate::assistant_memory::now()).unwrap());
 let prepared=o.prepare_actual_call_with_peer_data(&g,&server,"One proposed subsequent round; actual DATA/body review before writer".into(),None,Some(data.clone()),&data_configuration(provider)).unwrap();let review=DataReview::capture(&o,&g,data,&prepared.request,crate::assistant_memory::now()).unwrap();let source=Source::capture_peer_data(o.clone(),&g,review.clone(),store,observe.clone()).unwrap();(f,a,g,o,main,prepared,review,source,observe,state)
}
#[test]fn exact_native_data_body_target_and_original_broker_answer_are_bound_once_without_new_execution(){
 for provider in["ollama","lmstudio"]{let(f,_a,g,o,_main,prepared,review,source,observe,_state)=data_setup(provider);let before=ledger(&f,&g);let body=prepared.request.body().clone();let broker=crate::cli_chat::goal_decision_fixture(source.clone());
  assert_eq!(broker.request["goalTarget"]["origin"],"goalPeerData");assert_eq!(broker.request["goalReview"]["approvalScope"],"exactReviewedPeerPlanningData");assert_eq!(broker.request["goalReview"]["data"]["actualRequestBody"],body);assert_eq!(broker.request["goalReview"]["newBudgetGranted"],false);assert_eq!(broker.request["goalReview"]["data"]["scope"]["maxUses"],1);assert_eq!(broker.request["goalReview"]["data"]["sources"]["modelProjection"]["items"].as_array().unwrap().len(),2);assert_eq!(o.workers(),0);
  let mut wrong=broker.request["goalTarget"].clone();wrong["leaseId"]=json!("another-native-lease");assert!(broker.panel_answer(true,wrong).is_err());assert_eq!(broker.count(),1);broker.assert_panel_isolation();broker.panel_answer(true,broker.request["goalTarget"].clone()).unwrap();assert!(broker.panel_answer(true,broker.request["goalTarget"].clone()).is_err());
  let approved=review.approve(broker.decision().unwrap(),&o,&g,&observe,crate::assistant_memory::now()).unwrap();assert!(!source.pending());assert_eq!(approved.reference().input_hash,model::fingerprint(&(&o.lease().id,&o.lease().model,&body)).unwrap());assert!(approved.matches_request(&o,&g,&prepared.request,&observe,crate::assistant_memory::now()));
  assert!(Source::capture_peer_data(o.clone(),&g,review,Arc::new(Store::existing_verified(&f.path.join("goals"),&root(&f)).unwrap().unwrap()),observe).is_err());
  // Approval is DATA only. The existing one-round catalogue/journal is NOT
  // promoted into another execution permit by obtaining this native decision.
  assert!(o.consume_actual_call(&g,"no-new-round-from-data-only-consent",prepared,crate::assistant_memory::now()).is_err());assert_eq!(o.workers(),0);assert_eq!(ledger(&f,&g),before);
 }
}
#[test]fn exact_data_review_yields_with_zero_workers_then_resumes_same_owner_and_budget_before_consumption(){
 let(f,_a,g,o,main,prepared,review,source,observe,_state)=data_setup("ollama");let store=Store::existing_verified(&f.path.join("goals"),&root(&f)).unwrap().unwrap();let lease=o.lease().clone();let before=ledger(&f,&g);assert_eq!(o.workers(),0);o.yield_for_decision(&store,&source,crate::assistant_memory::now()).unwrap();assert!(o.waiting_for_resource());assert!(source.current());
 let manual=main.runtime_resources().acquire("ollama",Arc::default(),None).unwrap();drop(manual);let broker=crate::cli_chat::goal_decision_fixture(source.clone());broker.panel_answer(true,broker.request["goalTarget"].clone()).unwrap();let decision=broker.decision().unwrap();o.resume_after_decision(&store,&source,crate::assistant_memory::now()).unwrap();let approved=review.approve(decision,&o,&g,&observe,crate::assistant_memory::now()).unwrap();assert_eq!(o.lease(),&lease);assert!(!o.waiting_for_resource());assert!(approved.matches_request(&o,&g,&prepared.request,&observe,crate::assistant_memory::now()));assert_eq!(o.workers(),0);assert_eq!(ledger(&f,&g),before);
}
#[test]fn transient_proof_unavailability_retains_original_request_but_never_authorizes_and_refusal_remains_available(){
 let(f,_a,g,o,_main,_prepared,review,source,observe,state)=data_setup("ollama");let before=ledger(&f,&g);let broker=crate::cli_chat::goal_decision_fixture(source.clone());state.lock().unwrap().mode=1;assert!(!source.current()&&source.pending());assert!(broker.panel_answer(true,broker.request["goalTarget"].clone()).is_err());assert_eq!(broker.count(),1);state.lock().unwrap().mode=2;assert!(!source.current()&&source.pending());assert_eq!(broker.panel_pending().len(),1);broker.panel_answer(false,broker.request["goalTarget"].clone()).unwrap();assert!(review.approve(broker.decision().unwrap(),&o,&g,&observe,crate::assistant_memory::now()).is_err());assert_eq!(ledger(&f,&g),before);assert_eq!(o.workers(),0);
}
#[test]fn changed_destination_or_credential_revokes_exact_data_consent_and_reactivation_never_revives_it(){
 for change in["endpoint","credential"]{let(f,_a,g,o,_main,prepared,review,source,observe,state)=data_setup("ollama");let before=ledger(&f,&g);let broker=crate::cli_chat::goal_decision_fixture(source);broker.panel_answer(true,broker.request["goalTarget"].clone()).unwrap();let approved=review.approve(broker.decision().unwrap(),&o,&g,&observe,crate::assistant_memory::now()).unwrap();assert!(approved.matches_request(&o,&g,&prepared.request,&observe,crate::assistant_memory::now()));
  {let mut s=state.lock().unwrap();if change=="endpoint"{s.url="http://127.0.0.1:11445".into();}else{s.key=Some("synthetic-key-only".into());}}
  assert_eq!(approved.current(&o,&g,&observe,crate::assistant_memory::now()),Validity::Changed);{let mut s=state.lock().unwrap();s.url="http://127.0.0.1:11444".into();s.key=None;}assert_eq!(approved.current(&o,&g,&observe,crate::assistant_memory::now()),Validity::Changed);assert!(!approved.matches_request(&o,&g,&prepared.request,&observe,crate::assistant_memory::now()));assert_eq!(ledger(&f,&g),before);assert_eq!(o.workers(),0);
 }
}
#[test]fn native_data_approval_cannot_be_retargeted_to_a_new_actual_body_and_voice_cannot_approve_unread_data(){
 let(f,_a,g,o,_main,prepared,review,source,observe,_state)=data_setup("ollama");let before=ledger(&f,&g);let broker=crate::cli_chat::goal_decision_fixture(source);let code=broker.request["voiceCode"].as_str().unwrap();let stop=AtomicBool::new(false);let read=broker.voice("ollama",&format!("rever receita {code}"),&stop).unwrap();assert!(read.contains("não li o conteúdo integral"));let blocked=broker.voice("ollama",&format!("aprovar receita {code}"),&stop).unwrap();assert!(blocked.contains("aprovação por voz ainda não está disponível"));assert_eq!(broker.count(),1);broker.panel_answer(true,broker.request["goalTarget"].clone()).unwrap();let approved=review.approve(broker.decision().unwrap(),&o,&g,&observe,crate::assistant_memory::now()).unwrap();let data=prepared.peer_data.clone();drop(prepared);let(_,server)=observe().unwrap();let other=o.prepare_actual_call_with_peer_data(&g,&server,"Different body after consent".into(),None,data,&crate::pet_config::defaults()).unwrap();assert!(!approved.matches_request(&o,&g,&other.request,&observe,crate::assistant_memory::now()));assert_eq!(ledger(&f,&g),before);assert_eq!(o.workers(),0);
}
#[test]fn stop_and_exact_original_expiry_end_data_consent_without_attempt_or_new_model_budget(){
 for stop in[false,true]{let(f,_a,g,o,_main,prepared,review,source,observe,_state)=data_setup("ollama");let before=ledger(&f,&g);let broker=crate::cli_chat::goal_decision_fixture(source);broker.panel_answer(true,broker.request["goalTarget"].clone()).unwrap();let approved=review.approve(broker.decision().unwrap(),&o,&g,&observe,crate::assistant_memory::now()).unwrap();if stop{o.live.hold.cancel();assert_eq!(approved.current(&o,&g,&observe,crate::assistant_memory::now()),Validity::Changed);}else{assert_eq!(approved.current(&o,&g,&observe,approved.reference().expires_at),Validity::Changed);}assert!(!approved.matches_request(&o,&g,&prepared.request,&observe,crate::assistant_memory::now()));assert_eq!(ledger(&f,&g),before);assert_eq!(o.workers(),0);}
}

#[test]fn identical_body_in_a_new_turn_cannot_reuse_original_native_data_decision(){
 let(f,_a,g,o,_main,prepared,review,source,observe,_state)=data_setup("ollama");let before=ledger(&f,&g);let body=prepared.request.body().clone();let original_turn=prepared.request.turn_binding().unwrap();let broker=crate::cli_chat::goal_decision_fixture(source);broker.panel_answer(true,broker.request["goalTarget"].clone()).unwrap();let approved=review.approve(broker.decision().unwrap(),&o,&g,&observe,crate::assistant_memory::now()).unwrap();assert_eq!(approved.reference().turn_id,original_turn.1);let data=prepared.peer_data.clone();drop(prepared);
 let(_,server)=observe().unwrap();let new=o.prepare_actual_call_with_peer_data(&g,&server,"One proposed subsequent round; actual DATA/body review before writer".into(),None,data,&data_configuration("ollama")).unwrap();assert_eq!(*new.request.body(),body);assert_ne!(new.request.turn_binding().unwrap(),original_turn);assert!(!approved.matches_request(&o,&g,&new.request,&observe,crate::assistant_memory::now()));assert_eq!(ledger(&f,&g),before);assert_eq!(o.workers(),0);
}
#[test]fn stopping_only_the_prepared_turn_ends_its_data_request_without_cancelling_the_goal_or_consuming_budget(){
 let(f,_a,g,o,_main,prepared,_review,source,_observe,_state)=data_setup("ollama");let before=ledger(&f,&g);let broker=crate::cli_chat::goal_decision_fixture(source.clone());prepared.reservation.channel().cancel_provider("ollama");assert!(!source.current()&&!source.pending());assert!(broker.panel_answer(true,broker.request["goalTarget"].clone()).is_err());assert_eq!(o.workers(),0);assert_eq!(ledger(&f,&g),before);assert!(o.current(crate::assistant_memory::now()));
}

#[test]fn original_answer_survives_busy_native_validation_without_new_body_turn_expiry_or_second_use(){
 let(f,_a,g,o,_main,prepared,review,source,observe,state)=data_setup("ollama");let before=ledger(&f,&g);let broker=crate::cli_chat::goal_decision_fixture(source);broker.panel_answer(true,broker.request["goalTarget"].clone()).unwrap();let decision=broker.decision().unwrap();let original_body=prepared.request.body().clone();let original_turn=prepared.request.turn_binding().unwrap();let original_expiry=review.expires_at;
 state.lock().unwrap().mode=1;assert!(matches!(review.approve_retained(&decision,&o,&g,&observe,crate::assistant_memory::now()),Err(model::Error::Busy)));state.lock().unwrap().mode=0;let approved=review.approve_retained(&decision,&o,&g,&observe,crate::assistant_memory::now()).unwrap();assert_eq!(approved.reference().expires_at,original_expiry);assert_eq!(approved.reference().turn_id,original_turn.1);assert_eq!(*prepared.request.body(),original_body);assert!(approved.matches_request(&o,&g,&prepared.request,&observe,crate::assistant_memory::now()));assert!(review.approve_retained(&decision,&o,&g,&observe,crate::assistant_memory::now()).is_err());assert_eq!(o.workers(),0);assert_eq!(ledger(&f,&g),before);
}
